package net.zartra.gui;
import java.io.*;import java.nio.charset.Charset;import java.util.*;import java.util.logging.Logger;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.junit.Test;import static org.junit.Assert.*;
public class ActionPipelineTest {
 @Test public void duplicatedActionGetsIndependentId(){ActionEntry a=new ActionEntry();ActionEntry b=a.duplicate();assertNotEquals(a.id,b.id);assertEquals(a.type,b.type);}
 @Test public void everyActionTypeParsesAndLegacyAliasesMigrate(){for(MenuAction.Type t:MenuAction.Type.values())assertEquals(t,MenuAction.parse(t.name()+": value").type);assertEquals(MenuAction.Type.CLOSE_MENU,MenuAction.parse("CLOSE").type);assertEquals(MenuAction.Type.REFRESH_MENU,MenuAction.parse("REFRESH").type);}
 @Test public void legacyFileIsBackedUpThenConvertedToLeftAction()throws Exception{File dir=new File(System.getProperty("java.io.tmpdir"),"zgui-migrate-"+System.nanoTime());assertTrue(dir.mkdirs());File f=new File(dir,"old.yml");String yaml="id: old\ntitle: Old\nrows: 3\nitems:\n  '0':\n    material: STONE\n    action: 'MESSAGE: hello'\n";write(f,yaml);MenuStorage s=new MenuStorage(dir,Logger.getLogger("test"));MenuDefinition d=s.load().get("old");assertNotNull(d);assertEquals("hello",d.items.get(0).actions(MenuClickType.LEFT).get(0).value);File backup=new File(dir,"old.yml.pre-action-migration.bak");assertTrue(backup.isFile());assertEquals(yaml,read(backup));}
 @Test public void malformedAndInvalidActionsAreIgnored()throws Exception{File dir=new File(System.getProperty("java.io.tmpdir"),"zgui-malformed-"+System.nanoTime());assertTrue(dir.mkdirs());File f=new File(dir,"bad.yml");write(f,"id: bad\ntitle: Bad\nrows: 3\nitems:\n  '0':\n    material: STONE\n    actions:\n      LEFT:\n      - {type: NOPE, value: x, chance: 100, delay: 0}\n      - {type: MESSAGE, value: y, chance: 101, delay: 0}\n");MenuDefinition d=new MenuStorage(dir,Logger.getLogger("test")).load().get("bad");assertTrue(d.items.get(0).actions(MenuClickType.LEFT).isEmpty());}
 private static void write(File f,String s)throws Exception{FileOutputStream o=new FileOutputStream(f);o.write(s.getBytes("UTF-8"));o.close();}private static String read(File f)throws Exception{byte[] b=new byte[(int)f.length()];FileInputStream i=new FileInputStream(f);i.read(b);i.close();return new String(b,"UTF-8");}
}